mapper.select:
SELECT FOLDER_ID,PARENT_FOLDER_ID,OWNER_USER_ID,SCOPE_TYPE,WS_ID,PROJ_ID,FOLDER_NAME,SORT_ORDER,REG_DT,UPD_DT, LEVEL AS DEPTH, SYS_CONNECT_BY_PATH(FOLDER_NAME,' / ') AS FOLDER_PATH FROM NOTE_FOLDERS WHERE SCOPE_TYPE=#{scopeType} AND NVL(WS_ID,-1)=NVL(#{wsId,jdbcType=NUMERIC},-1) AND NVL(PROJ_ID,-1)=NVL(#{projId,jdbcType=NUMERIC},-1)
AND OWNER_USER_ID=#{userId,jdbcType=NUMERIC}
START WITH PARENT_FOLDER_ID IS NULL CONNECT BY PRIOR FOLDER_ID=PARENT_FOLDER_ID ORDER SIBLINGS BY SORT_ORDER,FOLDER_NAME

mapper.update:
UPDATE NOTE_FOLDERS f SET f.FOLDER_NAME=#{folderName},f.UPD_DT=SYSDATE
WHERE f.FOLDER_ID=#{folderId}
  AND (f.OWNER_USER_ID=#{userId}
    OR (f.SCOPE_TYPE='WS' AND (
        EXISTS (SELECT 1 FROM WORKSPACES w WHERE w.WS_ID=f.WS_ID AND w.OWNER_ID=#{userId})
        OR EXISTS (SELECT 1 FROM WS_MEMBERS wm WHERE wm.WS_ID=f.WS_ID AND wm.USER_ID=#{userId} AND UPPER(NVL(wm.WS_ROLE,'MEMBER'))='ADMIN')
    ))
    OR (f.SCOPE_TYPE='PROJ' AND (
        EXISTS (SELECT 1 FROM PROJECTS p WHERE p.PROJ_ID=f.PROJ_ID AND p.LEADER_ID=#{userId})
        OR EXISTS (SELECT 1 FROM PROJ_MEMBERS pm WHERE pm.PROJ_ID=f.PROJ_ID AND pm.USER_ID=#{userId} AND UPPER(NVL(pm.PROJ_ROLE,'MEMBER'))='ADMIN')
    )))

