UPDATE NOTES n
   SET n.FOLDER_ID = #{folderId,jdbcType=NUMERIC},
       n.UPD_DT = SYSDATE
 WHERE n.NOTE_ID = #{noteId}
   AND (
        n.USER_ID = #{userId}
        OR (n.SCOPE_TYPE = 'WS' AND (
              EXISTS (SELECT 1 FROM WORKSPACES w WHERE w.WS_ID = n.WS_ID AND w.OWNER_ID = #{userId})
              OR EXISTS (SELECT 1 FROM WS_MEMBERS wm WHERE wm.WS_ID = n.WS_ID AND wm.USER_ID = #{userId} AND UPPER(NVL(wm.WS_ROLE,'MEMBER')) = 'ADMIN')
        ))
        OR (n.SCOPE_TYPE = 'PROJ' AND (
              EXISTS (SELECT 1 FROM PROJECTS p WHERE p.PROJ_ID = n.PROJ_ID AND p.LEADER_ID = #{userId})
              OR EXISTS (SELECT 1 FROM PROJ_MEMBERS pm WHERE pm.PROJ_ID = n.PROJ_ID AND pm.USER_ID = #{userId} AND UPPER(NVL(pm.PROJ_ROLE,'MEMBER')) = 'ADMIN')
        ))
   )
   AND (
        #{folderId,jdbcType=NUMERIC} IS NULL
        OR EXISTS (
            SELECT 1
              FROM NOTE_FOLDERS f
             WHERE f.FOLDER_ID = #{folderId,jdbcType=NUMERIC}
               AND f.SCOPE_TYPE = n.SCOPE_TYPE
               AND NVL(f.WS_ID,-1) = NVL(n.WS_ID,-1)
               AND NVL(f.PROJ_ID,-1) = NVL(n.PROJ_ID,-1)
        )
   )
